  1432	                lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1433	            }
  1434	            if (view->render_rev != 0u) {
  1435	                vmap_rot_why('S');
  1436	                vmap_rot_full(view);    /* 画布已有内容才值得烘 */
  1437	            }
  1438	        }
  1439	    } else {
  1440	        view->heading_switch_pending = 0;
  1441	        if (view->rcanvas) {
  1442	            lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1443	        }
  1444	        if (view->canvas) {
  1445	            lv_obj_clear_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1446	        }
  1447	        /* 正立路名只在航向朝上时用；退回正北后由烘焙路径接管。 */
  1448	        {
  1449	            int32_t i;
  1450	
  1451	            for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
  1452	                if (view->rot_label[i] != NULL) {
  1453	                    lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
  1454	                }
  1455	            }
  1456	            view->rot_label_n = 0;
  1457	        }
  1458	    }
  1459	
  1460	    /* 位置公式与标签开关都变了：按新公式重摆，再整幅重来一帧。 */
  1461	    view->last_pan_px = INT32_MIN;
  1462	    view->last_pan_py = INT32_MIN;
  1463	    vmap_view_apply_canvas_pos(view, view->pan_dx, view->pan_dy);
