  1504	/**
  1505	 * @brief 更新航向（0–360，正北 0，顺时针）与当前速度。
  1506	 */
  1507	void vmap_view_set_heading(vmap_view_t * view, float heading_deg, float speed_kph)
  1508	{
  1509	    double d = (double)heading_deg;
  1510	    int32_t target;
  1511	    int32_t delta;
  1512	
  1513	    if (!view || !view->canvas) {
  1514	        return;
  1515	    }
  1516	    if (!view->heading_up) {
  1517	        return;
  1518	    }
  1519	    if (!(d >= 0.0) || !(d < 360.0)) {
  1520	        /* NaN / 越界：角度不动，但帧外增量的记账照样要服务。 */
  1521	        vmap_rot_service(view);
  1522	        return;
  1523	    }
  1524	
  1525	    if (!view->heading_valid) {
  1526	        /* 首个航向无条件接受：否则停车时箭头指上、地图还是正北。 */
  1527	        view->heading_deg = d;
  1528	        view->heading_valid = true;
  1529	    } else if (speed_kph >= VMAP_ROT_MIN_KPH) {
  1530	        double diff = d - view->heading_deg;
  1531	
  1532	        /* 圆周低通：先把差值折到 -180..180，避免 359°→1° 绕一整圈。 */
  1533	        while (diff > 180.0) {
  1534	            diff -= 360.0;
  1535	        }
  1536	        while (diff < -180.0) {
  1537	            diff += 360.0;
  1538	        }
  1539	        view->heading_deg += diff * (double)VMAP_ROT_SMOOTH;
  1540	        while (view->heading_deg >= 360.0) {
  1541	            view->heading_deg -= 360.0;
  1542	        }
  1543	        while (view->heading_deg < 0.0) {
  1544	            view->heading_deg += 360.0;
  1545	        }
  1546	    } else {
  1547	        /* 低速：course 是噪声，保持上次朝向；增量仍要走服务拍。 */
  1548	        vmap_rot_service(view);
  1549	        return;
  1550	    }
  1551	
  1552	    /*
  1553	     * 航向朝上 ⇒ 地图转 -heading（顺时针为正）。
  1554	     * **只记账不立即烘**：`want_rot10` 是"待应用目标"，真正的应用与限频都在
  1555	     * `vmap_rot_service()` 里，并且和帧外增量合并到同一次重烘。
  1556	     * 每烘一次 ~138 ms（288×264，0.55 Mpx/s）；1° 步进时若不限频，3.6°/s 的弯道
  1557	     * 会有 3~4 次/秒（≈50% UI）。1200 ms ⇒ 最多 0.83 次/秒 —— 转弯时地图比真实
  1558	     * 航向慢半拍，单步会放大到 ~2°（用户 2026-10-28 接受"旋转慢一些"）。
  1559	     */
  1560	    target = ((int32_t)lround(-view->heading_deg * 10.0) % 3600 + 3600) % 3600;
  1561	    delta = ((target - view->want_rot10 + 3600 + 1800) % 3600) - 1800;
  1562	    if (abs((int)delta) >= VMAP_ROT_STEP_10) {
  1563	        view->want_rot10 = target;
  1564	    }
  1565	
  1566	    vmap_rot_service(view);
  1567	}
