  3148	static void view_canvas(const vmap_view_t * view, vmap_canvas_t * canvas,
  3149	    bool clip_dirty)
  3150	{
  3151	    uint8_t i;
  3152	
  3153	    canvas->buf = (uint16_t *)view->cbuf;
  3154	    canvas->w = view->w;
  3155	    canvas->h = view->h;
  3156	    canvas->stride = view->stride;
  3157	    vmap_render_clip_reset(canvas);
  3158	    if (!clip_dirty) {
  3159	        return;
  3160	    }
  3161	    for (i = 0; i < view->pump_dirty_n; i++) {
  3162	        vmap_render_clip_add(canvas,
  3163	            view->pump_dirty_x1[i], view->pump_dirty_y1[i],
  3164	            view->pump_dirty_x2[i], view->pump_dirty_y2[i]);
  3165	    }
  3166	}
  3167	
  3168	static void pump_dirty_add(vmap_view_t * view, int32_t x1, int32_t y1,
  3169	    int32_t x2, int32_t y2)
  3170	{
  3171	    uint8_t i;
  3172	
  3173	    if (!view || x1 >= x2 || y1 >= y2) {
  3174	        return;
  3175	    }
  3176	
  3177	    if (x1 < 0) {
  3178	        x1 = 0;
  3179	    }
  3180	    if (y1 < 0) {
  3181	        y1 = 0;
  3182	    }
  3183	    if (x2 > view->w) {
  3184	        x2 = view->w;
  3185	    }
  3186	    if (y2 > view->h) {
  3187	        y2 = view->h;
  3188	    }
  3189	    if (x1 >= x2 || y1 >= y2 || view->pump_dirty_n >= VMAP_RENDER_DIRTY_MAX) {
  3190	        return;
  3191	    }
  3192	
  3193	    i = view->pump_dirty_n;
  3194	    view->pump_dirty_x1[i] = x1;
  3195	    view->pump_dirty_y1[i] = y1;
  3196	    view->pump_dirty_x2[i] = x2;
  3197	    view->pump_dirty_y2[i] = y2;
  3198	    view->pump_dirty_n++;
  3199	}
  3200	
  3201	static void pump_dirty_from_scroll(vmap_view_t * view, int32_t sx, int32_t sy)
  3202	{
  3203	    const int32_t pad = (int32_t)VMAP_RENDER_DIRTY_PAD;
  3204	
  3205	    view->pump_dirty_n = 0;
  3206	    if (sx > 0) {
  3207	        pump_dirty_add(view, view->w - sx - pad, 0, view->w, view->h);
  3208	    } else if (sx < 0) {
  3209	        pump_dirty_add(view, 0, 0, -sx + pad, view->h);
  3210	    }
  3211	    if (sy > 0) {
  3212	        pump_dirty_add(view, 0, view->h - sy - pad, view->w, view->h);
  3213	    } else if (sy < 0) {
  3214	        pump_dirty_add(view, 0, 0, view->w, -sy + pad);
  3215	    }
  3216	}
  3217	
  3218	static bool pump_rects_overlap(int32_t ax1, int32_t ay1, int32_t ax2, int32_t ay2,
  3219	    int32_t bx1, int32_t by1, int32_t bx2, int32_t by2)
  3220	{
  3221	    return ax1 < bx2 && ax2 > bx1 && ay1 < by2 && ay2 > by1;
  3222	}
  3223	
  3224	static bool pump_tile_dirty(const vmap_view_t * view, int32_t tx, int32_t ty)
  3225	{
  3226	    const int32_t tile_size = 256;
  3227	    int32_t x1;
  3228	    int32_t y1;
  3229	    int32_t x2;
  3230	    int32_t y2;
  3231	    uint8_t i;
  3232	
  3233	    if (!view || view->pump_dirty_n == 0) {
  3234	        return true;
  3235	    }
  3236	
  3237	    x1 = (int32_t)lround((tx * tile_size - view->pump_cx) * view->scale
  3238	        + view->w / 2.0);
  3239	    y1 = (int32_t)lround((ty * tile_size - view->pump_cy) * view->scale
  3240	        + view->h / 2.0);
  3241	    x2 = (int32_t)lround(x1 + 256.0 * view->scale);
  3242	    y2 = (int32_t)lround(y1 + 256.0 * view->scale);
  3243	
  3244	    for (i = 0; i < view->pump_dirty_n; i++) {
  3245	        if (pump_rects_overlap(x1, y1, x2, y2,
  3246	                view->pump_dirty_x1[i], view->pump_dirty_y1[i],
  3247	                view->pump_dirty_x2[i], view->pump_dirty_y2[i])) {
  3248	            return true;
  3249	        }
  3250	    }
  3251	    return false;
  3252	}
  3253	
  3254	static bool pump_advance(vmap_view_t * view)
  3255	{
  3256	    view->pump_ty--;
  3257	    if (view->pump_ty < view->pump_ty_min) {
  3258	        view->pump_tx--;
  3259	        view->pump_ty = view->pump_ty_max;
  3260	    }
  3261	    return view->pump_tx >= view->pump_tx_min;
  3262	}
  3263	
  3264	static void render_begin(vmap_view_t * view, bool reset_view, bool force_clear)
  3265	{
  3266	    vmap_canvas_t canvas;
  3267	    const double origin_lon = reset_view ? view->lon : view->render_lon;
  3268	    const double origin_lat = reset_view ? view->lat : view->render_lat;
  3269	    int32_t sx;
  3270	    int32_t sy;
  3271	    bool scrolled = false;
  3272	
  3273	    /* 先置"帧在飞"再做任何 C 修改：期间的位置更新不能烘半成品。
  3274	     * 两条路径（reset_view / keep-pan）都必须置位，否则泵不会推进。 */
  3275	    view->pump_phase = 1;
  3276	    view->pump_need_region = 1;
  3277	
  3278	    /* fopen/.vpk index belongs on the first pump tick, not GNSS/REC/set_view. */
  3279	
  3280	    vmap_perf_frame_begin();
  3281	    VMAP_PERF_T0();
  3282	    dvfs_map_busy(true);
  3283	    view->pump_dirty_n = 0;
  3284	    sx = (view->last_pan_px == INT32_MIN) ? (int32_t)lround(view->pan_dx)
  3285	                                         : view->last_pan_px;
  3286	    sy = (view->last_pan_py == INT32_MIN) ? (int32_t)lround(view->pan_dy)
  3287	                                         : view->last_pan_py;
  3288	
  3289	    if (reset_view) {
  3290	        /*
  3291	         * A hidden page can jump much farther than the last on-screen pan.
  3292	         * Derive the pixel migration from the two geographic origins instead
  3293	         * of trusting last_pan_px.  Otherwise a 1 km jump with a 14 px old pan
  3294	         * scrolls only 14 px, then marks the whole interior as the new origin.
  3295	         */
  3296	        const int32_t disp_sx = sx;     /* 当前屏上整数位移 */
  3297	        const int32_t disp_sy = sy;
  3298	        double base_lon = origin_lon;
  3299	        double base_lat = origin_lat;
  3300	        double rx = 0.0;
  3301	        double ry = 0.0;
  3302	
  3303	        if (!force_clear && view->render_rev > 0
  3304	            && view->paint_zoom == view->zoom
  3305	            && view->paint_scale == view->scale) {
  3306	            double old_x = 0.0;
  3307	            double old_y = 0.0;
  3308	            double new_x = 0.0;
  3309	            double new_y = 0.0;
  3310	            double dsx;
  3311	            double dsy;
  3312	
  3313	            vmap_latlong_to_pixel_d(view->render_lat, view->render_lon,
  3314	                view->zoom, &old_x, &old_y);
  3315	            vmap_latlong_to_pixel_d(origin_lat, origin_lon,
  3316	                view->zoom, &new_x, &new_y);
  3317	            dsx = (new_x - old_x) * view->scale;
  3318	            dsy = (new_y - old_y) * view->scale;
  3319	            sx = (int32_t)lround(dsx);
  3320	            sy = (int32_t)lround(dsy);
  3321	
  3322	            /*
  3323	             * 亚像素重锚：若这次位移正是"屏上已经显示的那个整数位移"（拖动/跟车
  3324	             * 的延续），新原点只推进**整数**屏幕量：滚动 sx 像素 + 对象从 -sx 归 0，
  3325	             * 内容一像素都不重采样；剩下的 |小数| < 0.5 记在 pan_rx/pan_ry 里，
  3326	             * 下一拍 `view_apply_center()` 从浮点中心重新算出来。
  3327	             * 不做这一步的话，取整误差会被写进新原点，200 px 的拖动能变成 199 px。
  3328	             */
  3329	            if (sx == disp_sx && sy == disp_sy) {
  3330	                vmap_pixel_to_latlong_d(old_x + (double)sx / view->scale,
  3331	                    old_y + (double)sy / view->scale, view->zoom,
  3332	                    &base_lon, &base_lat);
  3333	                rx = dsx - (double)sx;
  3334	                ry = dsy - (double)sy;
  3335	            }
  3336	        }
  3337	
  3338	        bool can_scroll = !force_clear && view->render_rev > 0
  3339	            && view->paint_zoom == view->zoom
  3340	            && view->paint_scale == view->scale
  3341	            && (sx != 0 || sy != 0)
  3342	            && sx > -view->w && sx < view->w
  3343	            && sy > -view->h && sy < view->h;
  3344	
  3345	        view->render_lon = base_lon;
  3346	        view->render_lat = base_lat;
  3347	        view_canvas(view, &canvas, false);
  3348	        if (can_scroll) {
  3349	            {
  3350	                VMAP_PERF_T0S();
  3351	                vmap_render_scroll(&canvas, sx, sy, vmap_style_bg565());
  3352	                pump_dirty_from_scroll(view, sx, sy);
  3353	                VMAP_PERF_T1S(scroll);
  3354	            }
  3355	            {
  3356	                VMAP_PERF_T0S();
  3357	                vmap_label_retained_scroll(&view->label_col, sx, sy,
  3358	                    VMAP_RENDER_DIRTY_MAX, &view->pump_dirty_n,
  3359	                    view->pump_dirty_x1, view->pump_dirty_y1,
  3360	                    view->pump_dirty_x2, view->pump_dirty_y2);
  3361	                VMAP_PERF_T1S(lscroll);
  3362	            }
  3363	            scrolled = true;
  3364	            {
  3365	                VMAP_PERF_T0S();
  3366	                lv_obj_invalidate(view->canvas);
  3367	                VMAP_PERF_T1S(inval);
  3368	            }
  3369	        } else {
  3370	            VMAP_PERF_T0S();
  3371	            vmap_render_clear(&canvas, vmap_style_bg565());
  3372	            vmap_label_retained_reset(&view->label_col);
  3373	            VMAP_PERF_T1S(scroll);  /* 清屏路径复用同一格 */
  3374	        }
  3375	
  3376	        view->pan_dx = 0.0;
  3377	        view->pan_dy = 0.0;
  3378	        view->last_pan_px = INT32_MIN;
  3379	        view->last_pan_py = INT32_MIN;
  3380	        vmap_view_apply_canvas_pos(view, 0.0, 0.0);
  3381	        /* 新的亚像素余量：相对**新原点**的请求位移（下一次 apply 会重新算，
  3382	         * 这里存下来只为 get_pan/诊断与 y_bias 重摆时保持连续）。 */
  3383	        view->pan_rx = rx;
  3384	        view->pan_ry = ry;
  3385	    } else {
  3386	        /* keep-pan redraw repaints every base tile, erasing all baked labels. */
  3387	        vmap_label_retained_reset(&view->label_col);
  3388	    }
  3389	
  3390	    vmap_label_collector_reset(&view->label_col);
  3391	    view->label_col.clip_n = 0;
  3392	    vmap_label_collector_set_focus(&view->label_col,
  3393	        view->w / 2 + (int32_t)lround(view->pan_dx),
  3394	        view->h / 2 + (int32_t)lround(view->pan_dy));
  3395	
  3396	    /* 浮点投影原点：与滚动后的像素同一网格（整数部分已滚走，小数留在这里）。 */
  3397	    vmap_latlong_to_pixel_d(view->render_lat, view->render_lon, view->zoom,
  3398	        &view->pump_cx_d, &view->pump_cy_d);
  3399	    view->pump_cx = (int)lround(view->pump_cx_d);
  3400	    view->pump_cy = (int)lround(view->pump_cy_d);
  3401	    /*
  3402	     * ring=0（2026-10-27，对齐 X-TRACK 的 tile rect 语义）：
