   846	static void tile_range(int32_t center_x, int32_t center_y, int32_t canvas_w,
   847	    int32_t canvas_h, double scale, int32_t ring,
   848	    int32_t * tx_min, int32_t * ty_min, int32_t * tx_max, int32_t * ty_max)
   849	{
   850	    const int32_t tile_size = 256;
   851	    double half_w = (canvas_w / 2.0) / scale;
   852	    double half_h = (canvas_h / 2.0) / scale;
   853	    double pad = (double)ring * tile_size;
   854	    double left = (double)center_x - half_w - pad;
   855	    double top = (double)center_y - half_h - pad;
   856	    double right = (double)center_x + half_w + pad;
   857	    double bottom = (double)center_y + half_h + pad;
   858	
   859	    *tx_min = (int32_t)(left / tile_size) - (left < 0 ? 1 : 0);
   860	    *ty_min = (int32_t)(top / tile_size) - (top < 0 ? 1 : 0);
   861	    *tx_max = (int32_t)(right / tile_size);
   862	    *ty_max = (int32_t)(bottom / tile_size);
   863	}
